#!/usr/bin/env bash
set -euo pipefail
# QA-03: bounded playback-regression / switching-soak harness.
#
# Pure JVM: no emulator, no Android SDK, no external network. The only socket is a
# short-lived HTTP source bound to the loopback address inside the harness itself.
# It calls only existing :core entry points (PlaylistParser, PlayerReusePolicy,
# StreamDoctor) and uses the deterministic channel fixture already generated by
# QA-02 when it is present. No core, Gradle, app or workflow file is modified.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
OUT="build/qa-playback-soak"
rm -rf "$OUT"
mkdir -p "$OUT/classes"

# Reuse the QA-02 loopback fixture when the build job already generated it. The
# fallback is a tiny deterministic playlist, never contacted as a network source.
FIXTURE="build/qa-epg-fixture/playlist.m3u"
if [ ! -s "$FIXTURE" ]; then
  FIXTURE="$OUT/playlist.m3u"
  python3 - "$FIXTURE" <<'PY'
import sys
with open(sys.argv[1], "w", encoding="utf-8", newline="\n") as out:
    out.write("#EXTM3U\n")
    for i in range(128):
        out.write('#EXTINF:-1 tvg-id="qa.soak.%d",Soak Channel %d\n' % (i, i))
        out.write("https://qa.invalid/live/soak-%03d.m3u8\n" % i)
PY
fi

# Resolve the existing :core runtime classpath with the checked-in print-only
# init script used by the QA-02 harness. No Gradle file is changed.
./gradlew --no-daemon --offline -I qa/fixtures/core-classpath.init.gradle.kts \
  :core:classes :printQaClasspath > "$OUT/gradle.log" 2>&1 || {
  echo "FAIL qa-playback-soak-classpath: Gradle could not resolve :core"
  tail -60 "$OUT/gradle.log"
  exit 1
}
CP="$(cat build/qa-core-classpath.txt)"
case "$CP" in
  *\;*) SEP=';' ;;
  *) SEP=':' ;;
esac

javac -encoding UTF-8 -cp "$CP" -d "$OUT/classes" scripts/QaPlaybackSoakCheck.java

timeout 120 java -Xms32m -Xmx256m -XX:+ExitOnOutOfMemoryError \
  -cp "$OUT/classes${SEP}${CP}" QaPlaybackSoakCheck "$FIXTURE" | tee "$OUT/report.txt"

# The harness emits its own privacy assertion. This second scan checks the bytes
# actually written to the report, and the negative control proves the scan is live.
if grep -q 'SENTINEL-' "$OUT/report.txt"; then
  echo "FAIL qa-playback-soak-log-privacy: a sensitive sentinel reached the report"
  exit 1
fi
printf '%s\n' 'SENTINEL-CREDENTIAL-51c9' > "$OUT/negative-control.txt"
if ! grep -q 'SENTINEL-' "$OUT/negative-control.txt"; then
  echo "FAIL qa-playback-soak-log-privacy: negative control was not detected"
  exit 1
fi
rm -f "$OUT/negative-control.txt"

grep -q '^PLAYBACK SOAK CHECK PASS$' "$OUT/report.txt"
echo "QA-03 playback soak check: PASS"
